insert into public.videos (id, chapter_id, title, description, duration_seconds, thumbnail_url, source_url, notes_url, is_free, view_count, sort) values
  ('f9b3a71a-3d7c-4cb7-a96b-d0c2e161723a', 'd42c8095-667c-47b3-97b3-ebc8ff919919', 'Introduction to Polynomial Functions', 'Defines polynomial functions and identifies their degree, leading coefficient and constant term, with examples of linear, quadratic and cubic functions.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, true, 3849, 1),
  ('0c78dadf-d2dc-4a0a-ad54-05fb3522d5ac', 'd42c8095-667c-47b3-97b3-ebc8ff919919', 'Polynomial Division and the Division Algorithm', 'Works through long division and synthetic division of polynomials and writes the result in the form f(x) = d(x)q(x) + r(x).', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, true, 502, 2),
  ('7eb84a1c-2d79-4e7f-b3fe-b9a778da7f60', 'd42c8095-667c-47b3-97b3-ebc8ff919919', 'The Remainder Theorem, Factor Theorem and Rational Zeros', 'Uses the remainder and factor theorems to find remainders and factors quickly, and the rational root theorem to list the possible rational zeros of a polynomial.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 2725, 3),
  ('dcc03109-c55b-4c34-8dd9-6cd252a79139', '786ef8f4-f9f8-42d9-947d-6441c15cbece', 'Laws of Exponents and Logarithms', 'Reviews the laws of exponents, defines the logarithm as the inverse of exponentiation, and applies the product, quotient and power laws of logarithms.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 1206, 1),
  ('dda34556-ae46-4189-b82e-6771d0281509', '786ef8f4-f9f8-42d9-947d-6441c15cbece', 'Graphs of Exponential and Logarithmic Functions', 'Sketches y = aˣ and y = logₐ x, compares exponential growth and decay, and identifies the domain, range, intercepts and asymptotes of each graph.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 1058, 2),
  ('50101108-05fe-46c9-9b65-1f1ad93facf8', '786ef8f4-f9f8-42d9-947d-6441c15cbece', 'Exponential Equations and Applications', 'Solves exponential and logarithmic equations and applies them to compound interest and population growth problems.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 3445, 3),
  ('000c826b-7053-42b4-bbba-9c0a91c8565e', 'a1c54497-51b5-4534-9dd9-82de11dba1f8', 'Reading: Population Growth', 'Reads a passage on the causes and effects of rapid population growth in Ethiopia and the world, and practises word formation and phrasal verbs from the text.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, true, 2382, 1),
  ('335516ab-7522-4ca6-b046-2807e759240c', 'a1c54497-51b5-4534-9dd9-82de11dba1f8', 'Degrees of Comparison', 'Reviews comparative and superlative forms, irregular forms such as good, better, best, and the as … as structure, using population data for practice.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, true, 1171, 2),
  ('32eb7e6d-1eb6-4284-b309-dc1613133a40', 'a1c54497-51b5-4534-9dd9-82de11dba1f8', 'Simple Present vs. Present Perfect', 'Contrasts the simple present for general facts with the present perfect for changes that started in the past and continue up to now.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 3537, 3),
  ('aabe3bad-059f-4eb1-83a2-579ad6c332ac', '5465ae28-8f50-43fa-8748-8a0e1f7a56ce', 'Reading: Travel Behaviors', 'Reads a passage on why and how people travel, and learns travel vocabulary and phrasal verbs such as set off, check in and get around.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 1559, 1),
  ('87e8ea3f-a72a-4d39-a177-de668f1cd53a', '5465ae28-8f50-43fa-8748-8a0e1f7a56ce', 'The Simple Past Tense', 'Practises regular and irregular past forms for describing trips and past experiences, including negatives and questions with did.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 4187, 2),
  ('0fba2be8-5c36-4065-b37d-d9c34d9fdc2c', '5465ae28-8f50-43fa-8748-8a0e1f7a56ce', 'Simple, Compound and Complex Sentences', 'Identifies sentence types by their structure and shows how to join ideas with coordinating and subordinating conjunctions when writing about a journey.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 173, 3),
  ('13a68c0c-74f4-4404-b48a-984568ba71f8', '512c6158-2a50-4f10-843d-d0d989fd4826', 'Scalars and Vectors', 'Distinguishes scalar quantities such as mass and time from vector quantities such as displacement and force, and shows how vectors are represented by arrows.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, true, 841, 1),
  ('eb7c3450-a74c-4958-91c9-9468a88b557b', '512c6158-2a50-4f10-843d-d0d989fd4826', 'Adding Vectors Graphically and Analytically', 'Adds vectors with the triangle and parallelogram methods, and uses Pythagoras'' theorem and trigonometry to find the magnitude and direction of the resultant.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, true, 1762, 2),
  ('b30110b9-035e-4146-80be-a00976e8e793', '512c6158-2a50-4f10-843d-d0d989fd4826', 'Resolving Vectors into Components', 'Splits a vector into horizontal and vertical components using sine and cosine, and adds vectors by adding their components.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 372, 3),
  ('77d947f2-704b-432d-8325-5ef94c5a452a', '56ef7c05-1389-4d55-a484-99de87209243', 'Average and Instantaneous Velocity', 'Explains the difference between average and instantaneous velocity and shows how to find each from a position–time graph.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 2884, 1),
  ('90e7d3a0-7598-487b-905a-93f4ba378be9', '56ef7c05-1389-4d55-a484-99de87209243', 'Equations of Motion with Constant Acceleration', 'Derives and applies v = u + at, s = ut + ½at² and v² = u² + 2as to solve problems about cars, buses and runners.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 3162, 2),
  ('508cbf53-8db2-42c4-9e34-4d3432f2da6a', '56ef7c05-1389-4d55-a484-99de87209243', 'Free Fall and Vertical Motion', 'Applies the equations of motion to objects dropped or thrown vertically, taking g ≈ 10 m/s² and ignoring air resistance.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 4232, 3),
  ('94529ece-47a3-4572-a5c8-2f863b76a2cd', 'af5ad483-f4cb-4313-8956-ab3bb761b44b', 'Writing and Balancing Chemical Equations', 'Applies the law of conservation of mass to write balanced chemical equations with state symbols, step by step.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, true, 1216, 1),
  ('d9916bf7-1d93-4ba5-bbc8-e5327e9ec449', 'af5ad483-f4cb-4313-8956-ab3bb761b44b', 'Types of Chemical Reactions', 'Classifies reactions as combination, decomposition, single displacement or double displacement, and introduces oxidation and reduction.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, true, 1111, 2),
  ('710e49b1-3efe-4244-8f2f-1a632a91cb73', 'af5ad483-f4cb-4313-8956-ab3bb761b44b', 'Mole Ratios, Limiting Reactants and Percent Yield', 'Uses balanced equations to calculate moles and masses of products, identify the limiting reactant and find the percent yield of a reaction.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 1143, 3),
  ('79c57670-8447-44ad-b8fb-5f94ff45b4ce', '18c7a9fd-fa12-4d33-9060-d41cf4adaa52', 'Solutions, Solutes and Solvents', 'Defines a solution and its components, compares solutions with suspensions and colloids, and explains the dissolving process and the rule “like dissolves like”.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 3199, 1),
  ('31f4b2b8-9c33-4be1-845a-0f6d087dc2a5', '18c7a9fd-fa12-4d33-9060-d41cf4adaa52', 'Solubility and the Factors That Affect It', 'Explains saturated, unsaturated and supersaturated solutions and how temperature, pressure and the nature of the solute and solvent affect solubility.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 519, 2),
  ('98de3961-6f65-43cb-acfa-aca86e95b9e0', '18c7a9fd-fa12-4d33-9060-d41cf4adaa52', 'Concentration: Percent by Mass, Molarity and Dilution', 'Calculates the concentration of solutions as percent by mass and as molarity, and shows how to prepare a dilute solution using M₁V₁ = M₂V₂.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 2499, 3),
  ('397c7b2f-fa0d-4269-a890-0f15e7bc07e6', 'f585a237-a87b-4d1e-b4d6-8ebf8f94aaee', 'Carbohydrates and Food Tests', 'Describes monosaccharides, disaccharides and polysaccharides, and shows how to test foods for starch with iodine solution and for reducing sugars with Benedict''s solution.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, true, 1288, 1),
  ('d3e1710d-95f6-4e2d-bf09-41259b9be330', 'f585a237-a87b-4d1e-b4d6-8ebf8f94aaee', 'Proteins, Lipids and Nucleic Acids', 'Explains the building blocks and functions of proteins, lipids and nucleic acids, including peptide bonds and the double-helix structure of DNA.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, true, 4193, 2),
  ('c7c802cf-c8c8-45eb-beef-0a207c603958', 'f585a237-a87b-4d1e-b4d6-8ebf8f94aaee', 'Enzymes: How They Work', 'Explains the lock-and-key model of enzyme action and how temperature, pH and substrate concentration affect the rate of enzyme-controlled reactions.', 596, null, 'https://archive.org/download/BigBuckBunny_124/Content/big_buck_bunny_720p_surround.mp4', null, false, 1486, 3),
  ('8c1f4dc5-b619-4a90-9683-c4264863df87', 'bc6a4ec6-08c7-4aae-b556-953e088a0f0f', 'The Cell Cycle and Interphase', 'Describes the stages of the cell cycle (G₁, S, G₂ and the mitotic phase) and what happens to DNA during interphase.', 654, null, 'https://archive.org/download/ElephantsDream/ed_1024_512kb.mp4', null, false, 3538, 1),
  ('67d6a090-aaeb-4e42-aead-8f056c9a4fa8', 'bc6a4ec6-08c7-4aae-b556-953e088a0f0f', 'Mitosis and Cytokinesis', 'Follows the chromosomes through prophase, metaphase, anaphase and telophase, and compares cytokinesis in plant and animal cells.', 596, null, 'https://storage.googleapis.com/exoplayer-test-media-0/BigBuckBunny_320x180.mp4', null, false, 1794, 2),
  ('f44a30f1-2ccb-4c9b-a726-03f0a79345bd', 'bc6a4ec6-08c7-4aae-b556-953e088a0f0f', 'Meiosis and Genetic Variation', 'Explains the two divisions of meiosis, crossing over and independent assortment, and compares meiosis with mitosis.', 888, null, 'https://archive.org/download/Sintel/sintel-2048-surround_512kb.mp4', null, false, 4570, 3)
insert into public.questions (id, subject_id, chapter_id, stem, options, correct_option, explanation, difficulty, is_free, sort) values
  ('9101531a-5626-4f25-a083-4c995d5a0dce', 'ee3ba694-d8c9-44ed-9428-ec908d7f7b9c', 'd42c8095-667c-47b3-97b3-ebc8ff919919', 'What are the degree and the leading coefficient of f(x) = 3x⁴ − 2x⁵ + 7x − 1?', '[{"key":"A","text":"Degree 4, leading coefficient 3"},{"key":"B","text":"Degree 5, leading coefficient −2"},{"key":"C","text":"Degree 5, leading coefficient 2"},{"key":"D","text":"Degree 4, leading coefficient −1"}]'::jsonb, 'B', 'The highest power of x is x⁵, so the degree is 5. The leading coefficient is the coefficient of that term, which is −2.', 1, true, 1),
  ('def68eb6-b631-486a-aae0-0903b7717902', 'ee3ba694-d8c9-44ed-9428-ec908d7f7b9c', 'd42c8095-667c-47b3-97b3-ebc8ff919919', 'What is the remainder when f(x) = x³ − 4x² + 2x + 5 is divided by x − 3?', '[{"key":"A","text":"2"},{"key":"B","text":"−2"},{"key":"C","text":"−64"},{"key":"D","text":"5"}]'::jsonb, 'A', 'By the remainder theorem, the remainder is f(3) = 3³ − 4(3²) + 2(3) + 5 = 27 − 36 + 6 + 5 = 2.', 2, true, 2),
  ('bcb0341e-78cd-4a3f-8c78-2fec3cb781b4', 'ee3ba694-d8c9-44ed-9428-ec908d7f7b9c', 'd42c8095-667c-47b3-97b3-ebc8ff919919', 'For what value of k is x + 2 a factor of p(x) = x³ + kx² − x − 2?', '[{"key":"A","text":"−2"},{"key":"B","text":"1"},{"key":"C","text":"2"},{"key":"D","text":"4"}]'::jsonb, 'C', 'By the factor theorem, p(−2) = 0: (−2)³ + k(−2)² − (−2) − 2 = −8 + 4k + 2 − 2 = 4k − 8 = 0, so k = 2.', 2, true, 3),
  ('b4fb96d2-3fde-4cdd-8b87-42dfb1d527c9', 'ee3ba694-d8c9-44ed-9428-ec908d7f7b9c', 'd42c8095-667c-47b3-97b3-ebc8ff919919', 'The rational root theorem gives a list of possible rational zeros of f(x) = 2x³ − 3x² + 5x + 6. Which of the following is NOT on that list?', '[{"key":"A","text":"−6"},{"key":"B","text":"3/2"},{"key":"C","text":"−1/2"},{"key":"D","text":"1/3"}]'::jsonb, 'D', 'A possible rational zero p/q must have p dividing the constant term 6 and q dividing the leading coefficient 2, giving ±1, ±2, ±3, ±6, ±1/2 and ±3/2. The denominator of 1/3 is 3, which does not divide 2, so 1/3 is not on the list.', 3, true, 4),
  ('5a1bc032-ad13-4410-a330-f405c00852dd', 'ee3ba694-d8c9-44ed-9428-ec908d7f7b9c', '786ef8f4-f9f8-42d9-947d-6441c15cbece', 'Evaluate log 20 + log 5, where the logarithms are to base 10.', '[{"key":"A","text":"log 25"},{"key":"B","text":"1"},{"key":"C","text":"2"},{"key":"D","text":"100"}]'::jsonb, 'C', 'By the product law, log 20 + log 5 = log (20 × 5) = log 100 = 2, because 10² = 100.', 1, false, 1),
  ('418e48f9-9da3-49f0-80e9-a33a74c27df9', 'ee3ba694-d8c9-44ed-9428-ec908d7f7b9c', '786ef8f4-f9f8-42d9-947d-6441c15cbece', 'Solve for x: 3ˣ⁺¹ = 81', '[{"key":"A","text":"2"},{"key":"B","text":"3"},{"key":"C","text":"4"},{"key":"D","text":"27"}]'::jsonb, 'B', 'Write 81 as a power of 3: 81 = 3⁴. Then 3ˣ⁺¹ = 3⁴, so x + 1 = 4 and x = 3.', 1, false, 2),
  ('165d43c9-6a09-4932-a698-fc955e3dd08a', 'ee3ba694-d8c9-44ed-9428-ec908d7f7b9c', '786ef8f4-f9f8-42d9-947d-6441c15cbece', 'Almaz deposits 10,000 birr in a savings account that pays 10% interest compounded annually. How much money will she have after 2 years?', '[{"key":"A","text":"12,000 birr"},{"key":"B","text":"11,000 birr"},{"key":"C","text":"12,210 birr"},{"key":"D","text":"12,100 birr"}]'::jsonb, 'D', 'A = P(1 + r)ⁿ = 10,000 × (1.10)² = 10,000 × 1.21 = 12,100 birr. Simple interest would give only 12,000 birr, because it ignores interest earned on interest.', 2, false, 3),
  ('99e92b5f-5ab7-4058-8e66-9b519bd62348', 'ee3ba694-d8c9-44ed-9428-ec908d7f7b9c', '786ef8f4-f9f8-42d9-947d-6441c15cbece', 'Solve for x: log₂ x + log₂ (x − 2) = 3', '[{"key":"A","text":"x = 4 only"},{"key":"B","text":"x = −2 only"},{"key":"C","text":"x = 4 or x = −2"},{"key":"D","text":"x = 2"}]'::jsonb, 'A', 'log₂ [x(x − 2)] = 3, so x(x − 2) = 2³ = 8, giving x² − 2x − 8 = 0 and (x − 4)(x + 2) = 0. x = −2 is rejected because log₂ of a negative number is undefined, so x = 4 only.', 3, false, 4),
  ('12752554-d423-4116-9a71-b070c8157287', '302bf00e-110c-4ef8-bbf7-a1909def0dbc', 'a1c54497-51b5-4534-9dd9-82de11dba1f8', 'Choose the correct word: “Ethiopia is one of the _____ populous countries in Africa.”', '[{"key":"A","text":"more"},{"key":"B","text":"much"},{"key":"C","text":"most"},{"key":"D","text":"many"}]'::jsonb, 'C', 'After “one of the” we need a superlative. “Populous” is a long adjective, so its superlative is formed with “most”: “the most populous”.', 1, true, 1),
  ('674ee071-29eb-4477-8fe9-2b25e98e126d', '302bf00e-110c-4ef8-bbf7-a1909def0dbc', 'a1c54497-51b5-4534-9dd9-82de11dba1f8', 'Choose the correct verb: “Since 1990, Ethiopia''s population _____ more than doubled.”', '[{"key":"A","text":"has"},{"key":"B","text":"is"},{"key":"C","text":"was"},{"key":"D","text":"have"}]'::jsonb, 'A', '“Since 1990” describes a change that started in the past and continues up to now, so the present perfect is needed. The subject “population” is singular, so the auxiliary is “has”.', 2, true, 2),
  ('1abd80fa-a0e4-4f46-9c08-37cc55d16702', '302bf00e-110c-4ef8-bbf7-a1909def0dbc', 'a1c54497-51b5-4534-9dd9-82de11dba1f8', 'Choose the correct relative pronoun: “Countries _____ populations grow quickly need to build more schools and health centres.”', '[{"key":"A","text":"who"},{"key":"B","text":"which"},{"key":"C","text":"whose"},{"key":"D","text":"whom"}]'::jsonb, 'C', '“Whose” shows possession: the populations belong to the countries. “Who” and “whom” refer to people, and “which” cannot be followed by a noun to show possession in this way.', 2, true, 3),
  ('8584c90b-3728-4b2b-8607-1adc72ba5e31', '302bf00e-110c-4ef8-bbf7-a1909def0dbc', 'a1c54497-51b5-4534-9dd9-82de11dba1f8', 'Read the passage and answer the question. “A growing population can be an advantage. When young people are healthy, educated and able to find productive jobs, they can speed up a country''s economic growth. However, if schools, health services and jobs do not expand as fast as the population, the same growth can lead to unemployment and pressure on farmland.” What is the writer''s main purpose?', '[{"key":"A","text":"To argue that population growth is always harmful"},{"key":"B","text":"To show that the effects of population growth depend on how well a country prepares for it"},{"key":"C","text":"To describe the history of Ethiopia''s population"},{"key":"D","text":"To persuade young people to move to cities"}]'::jsonb, 'B', 'The writer presents a possible benefit and a possible problem, and links the outcome to whether schools, health services and jobs keep up with the population. The passage never says growth is always harmful, and it does not discuss history or migration.', 3, true, 4),
  ('68a111b0-73f5-4a8a-84ae-c5eed83024e8', '302bf00e-110c-4ef8-bbf7-a1909def0dbc', '5465ae28-8f50-43fa-8748-8a0e1f7a56ce', 'Choose the correct verb: “Last year my family _____ to Lalibela by bus to celebrate Genna.”', '[{"key":"A","text":"go"},{"key":"B","text":"goes"},{"key":"C","text":"gone"},{"key":"D","text":"went"}]'::jsonb, 'D', '“Last year” refers to a finished time in the past, so the simple past is needed. “Go” is an irregular verb, and its simple past form is “went”.', 1, false, 1),
  ('cafa6ccf-07ec-4eb4-97c3-c05b5450cafc', '302bf00e-110c-4ef8-bbf7-a1909def0dbc', '5465ae28-8f50-43fa-8748-8a0e1f7a56ce', 'Choose the phrasal verb that best completes the sentence: “We _____ at 5:00 a.m. so that we could reach Gondar before dark.”', '[{"key":"A","text":"set off"},{"key":"B","text":"put off"},{"key":"C","text":"gave up"},{"key":"D","text":"ran out"}]'::jsonb, 'A', '“Set off” means to start a journey, which fits leaving early to arrive before dark. “Put off” means postpone, “gave up” means stopped trying and “ran out” means had none left.', 2, false, 2),
  ('d52c9508-479a-41c0-ac71-d73ab1df2afd', '302bf00e-110c-4ef8-bbf7-a1909def0dbc', '5465ae28-8f50-43fa-8748-8a0e1f7a56ce', 'What type of sentence is this? “Although the road was rough, we enjoyed the journey.”', '[{"key":"A","text":"Simple sentence"},{"key":"B","text":"Compound sentence"},{"key":"C","text":"Compound-complex sentence"},{"key":"D","text":"Complex sentence"}]'::jsonb, 'D', 'The sentence has one independent clause (“we enjoyed the journey”) and one dependent clause introduced by the subordinating conjunction “although”, so it is a complex sentence.', 2, false, 3),
  ('deecda11-7ead-4fc2-a120-b6fc9117e2bb', '302bf00e-110c-4ef8-bbf7-a1909def0dbc', '5465ae28-8f50-43fa-8748-8a0e1f7a56ce', 'Read the passage and choose the best summary. “Before the Addis Ababa–Djibouti railway opened, most travellers and goods between the two cities went by road, a journey that could take about three days. Today the electric train covers the distance in roughly twelve hours, and many traders prefer it because their goods arrive faster and more safely. Road transport, however, is still important for towns that the railway does not reach.”', '[{"key":"A","text":"The railway has completely replaced road transport between Ethiopia and Djibouti."},{"key":"B","text":"The electric railway has made travel between Addis Ababa and Djibouti much faster, but roads are still needed for other towns."},{"key":"C","text":"Traders prefer road transport because it is cheaper and safer."},{"key":"D","text":"The train journey from Addis Ababa to Djibouti takes about three days."}]'::jsonb, 'B', 'A good summary keeps the main points: the railway is much faster and popular with traders, but roads remain important for places the railway does not serve. The other options contradict the passage or give wrong details.', 3, false, 4),
  ('8aacb729-da21-4a10-9fa8-224449244ad3', '6fbfe10f-3986-4ca3-8937-126ded0804d3', '512c6158-2a50-4f10-843d-d0d989fd4826', 'Which of the following is a vector quantity?', '[{"key":"A","text":"Mass"},{"key":"B","text":"Temperature"},{"key":"C","text":"Displacement"},{"key":"D","text":"Time"}]'::jsonb, 'C', 'A vector has both magnitude and direction. Displacement (for example, 5 km north) is a vector, while mass, temperature and time have magnitude only, so they are scalars.', 1, true, 1),
  ('94de266e-60a1-4e5a-8aa7-1cfb8e7610a2', '6fbfe10f-3986-4ca3-8937-126ded0804d3', '512c6158-2a50-4f10-843d-d0d989fd4826', 'Two forces of 6 N and 8 N act on an object at right angles to each other. What is the magnitude of their resultant?', '[{"key":"A","text":"2 N"},{"key":"B","text":"10 N"},{"key":"C","text":"14 N"},{"key":"D","text":"48 N"}]'::jsonb, 'B', 'For two perpendicular forces, R = √(6² + 8²) = √(36 + 64) = √100 = 10 N.', 2, true, 2),
  ('9c7b4ce2-bc70-455d-ace6-c2c66f32c613', '6fbfe10f-3986-4ca3-8937-126ded0804d3', '512c6158-2a50-4f10-843d-d0d989fd4826', 'A rope pulls a cart with a force of 20 N at 30° above the horizontal. What is the horizontal component of the force? (cos 30° ≈ 0.866)', '[{"key":"A","text":"10.0 N"},{"key":"B","text":"11.5 N"},{"key":"C","text":"20.0 N"},{"key":"D","text":"17.3 N"}]'::jsonb, 'D', 'Horizontal component = F cos θ = 20 N × cos 30° = 20 × 0.866 ≈ 17.3 N. (10.0 N is the vertical component, F sin 30°.)', 2, true, 3),
  ('b7019c1e-0fb4-4ad5-a4c5-00590e1b0a4b', '6fbfe10f-3986-4ca3-8937-126ded0804d3', '512c6158-2a50-4f10-843d-d0d989fd4826', 'Two forces of 5 N and 12 N act at the same point. Which of the following CANNOT be the magnitude of their resultant?', '[{"key":"A","text":"4 N"},{"key":"B","text":"7 N"},{"key":"C","text":"13 N"},{"key":"D","text":"17 N"}]'::jsonb, 'A', 'The resultant lies between the difference and the sum of the forces: 12 − 5 = 7 N (opposite directions) up to 12 + 5 = 17 N (same direction). 13 N is possible when they are at right angles (√(5² + 12²) = 13), but 4 N is less than 7 N, so it is impossible.', 3, true, 4),
  ('3d4f8116-fca3-47ca-9e1d-8f0e03c509a1', '6fbfe10f-3986-4ca3-8937-126ded0804d3', '56ef7c05-1389-4d55-a484-99de87209243', 'What does the slope (gradient) of a velocity–time graph represent?', '[{"key":"A","text":"Displacement"},{"key":"B","text":"Acceleration"},{"key":"C","text":"Distance"},{"key":"D","text":"Speed"}]'::jsonb, 'B', 'Slope = change in velocity ÷ change in time, which is the definition of acceleration. The area under a velocity–time graph gives the displacement.', 1, false, 1),
  ('1c7b4787-b34b-4c02-973b-9ce2d9c449b5', '6fbfe10f-3986-4ca3-8937-126ded0804d3', '56ef7c05-1389-4d55-a484-99de87209243', 'A car moving at 20 m/s brakes uniformly and stops in 4 s. How far does it travel while braking?', '[{"key":"A","text":"40 m"},{"key":"B","text":"80 m"},{"key":"C","text":"20 m"},{"key":"D","text":"5 m"}]'::jsonb, 'A', 'For uniform acceleration, s = ½(u + v)t = ½ × (20 m/s + 0 m/s) × 4 s = 40 m.', 2, false, 2),
  ('d8043239-bb89-4940-90a8-6278eaeb5c63', '6fbfe10f-3986-4ca3-8937-126ded0804d3', '56ef7c05-1389-4d55-a484-99de87209243', 'A ball is thrown vertically upward with a speed of 20 m/s. What maximum height does it reach? (Take g = 10 m/s² and ignore air resistance.)', '[{"key":"A","text":"10 m"},{"key":"B","text":"40 m"},{"key":"C","text":"20 m"},{"key":"D","text":"200 m"}]'::jsonb, 'C', 'At the highest point v = 0. Using v² = u² − 2gh: 0 = 20² − 2 × 10 × h, so h = 400 ÷ 20 = 20 m.', 2, false, 3),
  ('be7c4208-b000-48a6-9000-6f9e86b9636a', '6fbfe10f-3986-4ca3-8937-126ded0804d3', '56ef7c05-1389-4d55-a484-99de87209243', 'A bus accelerates uniformly from 10 m/s to 30 m/s over a distance of 100 m. What is its acceleration?', '[{"key":"A","text":"0.2 m/s²"},{"key":"B","text":"2 m/s²"},{"key":"C","text":"8 m/s²"},{"key":"D","text":"4 m/s²"}]'::jsonb, 'D', 'Using v² = u² + 2as: 30² = 10² + 2 × a × 100, so 900 = 100 + 200a, which gives 200a = 800 and a = 4 m/s².', 3, false, 4),
  ('5ce14ca0-226e-4917-a29b-c06c276c6232', '27848640-bd58-4119-8ab0-65d07279880f', 'af5ad483-f4cb-4313-8956-ab3bb761b44b', 'What type of reaction is shown? Zn + CuSO₄ → ZnSO₄ + Cu', '[{"key":"A","text":"Combination"},{"key":"B","text":"Decomposition"},{"key":"C","text":"Single displacement"},{"key":"D","text":"Double displacement"}]'::jsonb, 'C', 'Zinc is more reactive than copper, so it replaces copper in copper(II) sulfate. One element displacing another from its compound is a single displacement reaction.', 1, true, 1),
  ('71c3ac30-32ff-447c-97c9-9e5885d1a040', '27848640-bd58-4119-8ab0-65d07279880f', 'af5ad483-f4cb-4313-8956-ab3bb761b44b', 'Which set of coefficients, in the order Al, O₂, Al₂O₃, balances the equation Al + O₂ → Al₂O₃?', '[{"key":"A","text":"2, 3, 1"},{"key":"B","text":"4, 3, 2"},{"key":"C","text":"1, 3, 2"},{"key":"D","text":"4, 2, 3"}]'::jsonb, 'B', '4Al + 3O₂ → 2Al₂O₃ has 4 aluminium atoms and 3 × 2 = 6 oxygen atoms on the left, and 2 × 2 = 4 aluminium atoms and 2 × 3 = 6 oxygen atoms on the right, so it is balanced.', 2, true, 2),
  ('26bacea9-68e1-471e-84f2-0a9c2e8cfe8d', '27848640-bd58-4119-8ab0-65d07279880f', 'af5ad483-f4cb-4313-8956-ab3bb761b44b', 'In the reaction N₂ + 3H₂ → 2NH₃, 2 mol of N₂ is mixed with 3 mol of H₂. What is the maximum amount of NH₃ that can form?', '[{"key":"A","text":"1 mol"},{"key":"B","text":"4 mol"},{"key":"C","text":"6 mol"},{"key":"D","text":"2 mol"}]'::jsonb, 'D', '2 mol of N₂ would need 2 × 3 = 6 mol of H₂, but only 3 mol is available, so H₂ is the limiting reactant. 3 mol of H₂ produces 3 × (2/3) = 2 mol of NH₃.', 2, true, 3),
  ('2c404a20-c9da-4994-803f-25d7f2754167', '27848640-bd58-4119-8ab0-65d07279880f', 'af5ad483-f4cb-4313-8956-ab3bb761b44b', 'When 10.0 g of CaCO₃ is heated, it decomposes: CaCO₃ → CaO + CO₂. If 4.2 g of CaO is obtained, what is the percent yield? (Ca = 40, C = 12, O = 16)', '[{"key":"A","text":"42%"},{"key":"B","text":"56%"},{"key":"C","text":"75%"},{"key":"D","text":"84%"}]'::jsonb, 'C', 'Molar mass of CaCO₃ = 40 + 12 + 3 × 16 = 100 g/mol, so 10.0 g = 0.100 mol, which can give 0.100 mol of CaO = 0.100 × 56 g = 5.6 g (theoretical yield). Percent yield = (4.2 ÷ 5.6) × 100 = 75%.', 3, true, 4),
  ('84029ec8-ab8c-4902-899a-6acb991c8d2b', '27848640-bd58-4119-8ab0-65d07279880f', '18c7a9fd-fa12-4d33-9060-d41cf4adaa52', 'Which of the following substances dissolves most readily in water?', '[{"key":"A","text":"Kerosene"},{"key":"B","text":"Table salt (NaCl)"},{"key":"C","text":"Candle wax"},{"key":"D","text":"Cooking oil"}]'::jsonb, 'B', 'Water is a polar solvent, and “like dissolves like”. Ionic sodium chloride dissolves well in water, while non-polar kerosene, wax and oil do not.', 1, false, 1),
  ('e307fdb0-a79b-4fb4-bebf-0897e2bf467e', '27848640-bd58-4119-8ab0-65d07279880f', '18c7a9fd-fa12-4d33-9060-d41cf4adaa52', 'A student dissolves 20 g of sugar in 180 g of water. What is the percent by mass of sugar in the solution?', '[{"key":"A","text":"11.1%"},{"key":"B","text":"20%"},{"key":"C","text":"10%"},{"key":"D","text":"90%"}]'::jsonb, 'C', 'Mass of solution = 20 g + 180 g = 200 g. Percent by mass = (20 g ÷ 200 g) × 100 = 10%.', 2, false, 2),
  ('84582e3a-7a3e-4c30-8f62-ed69d0be123b', '27848640-bd58-4119-8ab0-65d07279880f', '18c7a9fd-fa12-4d33-9060-d41cf4adaa52', 'What is the molarity of a solution made by dissolving 4.0 g of NaOH in enough water to make 500 mL of solution? (Na = 23, O = 16, H = 1)', '[{"key":"A","text":"0.20 M"},{"key":"B","text":"0.10 M"},{"key":"C","text":"0.80 M"},{"key":"D","text":"2.0 M"}]'::jsonb, 'A', 'Molar mass of NaOH = 23 + 16 + 1 = 40 g/mol, so 4.0 g ÷ 40 g/mol = 0.10 mol. Molarity = 0.10 mol ÷ 0.500 L = 0.20 M.', 2, false, 3),
  ('946cc8ef-c08f-4b23-8ceb-750706c095dd', '27848640-bd58-4119-8ab0-65d07279880f', '18c7a9fd-fa12-4d33-9060-d41cf4adaa52', 'How much water must be added to 50 mL of 2.0 M HCl to dilute it to 0.50 M?', '[{"key":"A","text":"100 mL"},{"key":"B","text":"200 mL"},{"key":"C","text":"150 mL"},{"key":"D","text":"250 mL"}]'::jsonb, 'C', 'M₁V₁ = M₂V₂ gives 2.0 M × 50 mL = 0.50 M × V₂, so V₂ = 200 mL. The volume of water to add is 200 mL − 50 mL = 150 mL.', 3, false, 4),
  ('d1d06c31-112d-47c4-a86c-bf73fa99f529', '3ec7a03b-c804-494b-bffa-d2bda07e8729', 'f585a237-a87b-4d1e-b4d6-8ebf8f94aaee', 'Which reagent turns blue-black when it is added to a food sample containing starch?', '[{"key":"A","text":"Benedict''s solution"},{"key":"B","text":"Iodine solution"},{"key":"C","text":"Biuret reagent"},{"key":"D","text":"Ethanol"}]'::jsonb, 'B', 'Iodine solution changes from yellow-brown to blue-black when starch is present. Benedict''s solution tests for reducing sugars, biuret reagent for proteins and ethanol for fats.', 1, true, 1),
  ('68bc7259-89aa-4043-920d-86c1fb10d5f1', '3ec7a03b-c804-494b-bffa-d2bda07e8729', 'f585a237-a87b-4d1e-b4d6-8ebf8f94aaee', 'Sucrose, the sugar produced from sugarcane at factories such as Wonji, is a disaccharide made of which two monosaccharides?', '[{"key":"A","text":"Glucose + glucose"},{"key":"B","text":"Glucose + galactose"},{"key":"C","text":"Glucose + fructose"},{"key":"D","text":"Fructose + galactose"}]'::jsonb, 'C', 'Sucrose forms when glucose and fructose join in a condensation reaction. Glucose + glucose forms maltose, and glucose + galactose forms lactose.', 2, true, 2),
  ('566429dd-3a2a-40c6-b0c0-88a7e8e4db6a', '3ec7a03b-c804-494b-bffa-d2bda07e8729', 'f585a237-a87b-4d1e-b4d6-8ebf8f94aaee', 'In a DNA molecule, 30% of the bases are adenine (A). What percentage of the bases are guanine (G)?', '[{"key":"A","text":"20%"},{"key":"B","text":"30%"},{"key":"C","text":"40%"},{"key":"D","text":"70%"}]'::jsonb, 'A', 'Adenine pairs with thymine, so T = 30% and A + T = 60%. The remaining 100% − 60% = 40% is shared equally between G and C, so G = 20%.', 3, true, 3),
  ('a3cedc1c-391a-4b25-9682-777f3166efa7', '3ec7a03b-c804-494b-bffa-d2bda07e8729', 'f585a237-a87b-4d1e-b4d6-8ebf8f94aaee', 'Why does the activity of a human enzyme fall sharply when it is heated to 70 °C?', '[{"key":"A","text":"The substrate is used up too quickly."},{"key":"B","text":"Molecules move more slowly at high temperatures."},{"key":"C","text":"The enzyme turns into a substrate."},{"key":"D","text":"The enzyme is denatured, so its active site changes shape and the substrate no longer fits."}]'::jsonb, 'D', 'Enzymes are proteins. High temperatures break the bonds that hold an enzyme''s shape, so its active site is permanently changed (denatured) and can no longer bind the substrate.', 2, true, 4),
  ('2ac0bdba-207c-4a6e-8fe4-03c7be9e924a', '3ec7a03b-c804-494b-bffa-d2bda07e8729', 'bc6a4ec6-08c7-4aae-b556-953e088a0f0f', 'During which phase of the cell cycle is DNA replicated?', '[{"key":"A","text":"G₁ phase"},{"key":"B","text":"S phase"},{"key":"C","text":"G₂ phase"},{"key":"D","text":"Metaphase"}]'::jsonb, 'B', 'DNA is copied during the S (synthesis) phase of interphase, so each chromosome consists of two identical sister chromatids before mitosis begins.', 1, false, 1),
  ('eb3c5f3a-94b5-443b-b686-392329881be5', '3ec7a03b-c804-494b-bffa-d2bda07e8729', 'bc6a4ec6-08c7-4aae-b556-953e088a0f0f', 'In which stage of mitosis do the chromosomes line up at the equator of the cell?', '[{"key":"A","text":"Prophase"},{"key":"B","text":"Anaphase"},{"key":"C","text":"Telophase"},{"key":"D","text":"Metaphase"}]'::jsonb, 'D', 'In metaphase, spindle fibres attach to the centromeres and the chromosomes line up along the equator (metaphase plate) before the sister chromatids separate in anaphase.', 1, false, 2),
  ('9140487d-549d-4ef3-93d4-cddb8edff73a', '3ec7a03b-c804-494b-bffa-d2bda07e8729', 'bc6a4ec6-08c7-4aae-b556-953e088a0f0f', 'A human cell with 46 chromosomes completes meiosis. What is produced?', '[{"key":"A","text":"2 cells, each with 46 chromosomes"},{"key":"B","text":"2 cells, each with 23 chromosomes"},{"key":"C","text":"4 cells, each with 23 chromosomes"},{"key":"D","text":"4 cells, each with 46 chromosomes"}]'::jsonb, 'C', 'Meiosis has two divisions, so one cell produces four cells. The chromosome number is halved, so each cell is haploid with 46 ÷ 2 = 23 chromosomes.', 2, false, 3),
  ('ddccb145-c111-4615-b7e0-5031dfbc898d', '3ec7a03b-c804-494b-bffa-d2bda07e8729', 'bc6a4ec6-08c7-4aae-b556-953e088a0f0f', 'Which event during meiosis produces new combinations of alleles on the same chromosome?', '[{"key":"A","text":"Crossing over between homologous chromosomes in prophase I"},{"key":"B","text":"Separation of sister chromatids in anaphase II"},{"key":"C","text":"DNA replication in the S phase"},{"key":"D","text":"Cytokinesis after telophase II"}]'::jsonb, 'A', 'In prophase I, homologous chromosomes pair up and non-sister chromatids exchange segments (crossing over). This mixes alleles from the maternal and paternal chromosomes, creating genetic variation.', 3, false, 4)
