  ('cf82f59e-c2b1-4aa3-aed8-b8b9d9e68d8b', 10, null, 'mock', 'Grade 10 Mock Test 1', 'Mixed questions from every subject, timed like the real exam.', null, null, 15, true, '2026-09-15', 1),
  ('4e7b6e83-081e-40d4-8867-d79439d8c2fa', 10, null, 'mock', 'Grade 10 Mock Test 2', 'Mixed questions from every subject, timed like the real exam.', null, null, 15, false, '2026-10-01', 2),
